/* eslint-disable max-len */
/* eslint-disable eqeqeq */
/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { CourseService } from 'src/app/data/service/course/course.service';
import { G } from '../../../../core/common/G';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { Urls } from '../../../../core/common/Urls';
import { GResponse } from '../../../../core/common/GResponse';
import { SliderService } from '../../../../data/service/site/Slider.service';

@Component({
  selector: 'app-runner',
  templateUrl: './runner.component.html',
  styleUrls: ['./runner.component.scss']
})
export class RunnerComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusVideo: string | SafeUrl = 'hy0QI';

  form: FormGroup;
  form2: FormGroup;
  form3: FormGroup;
  form4: FormGroup;
  form5: FormGroup;

  // rType = '1';
  runner_diameter2 = 5.64;
  pi = 3.14159265;
  v_sound = 360;
  m = 88200.0;
  m2 = 80850.0;

  cr = 10.86;
  cubic_capacity = 1587.46;
  runner_diameter = 3.36;
  runner_diameter_max = 3.51;
  runner_length1 = 71.80;
  runner_length2 = 35.90;
  runner_length3 = 23.93;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.isShow = false;
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(12).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.TunerPlusRunnerVideo;

    this.form = this.fb.group({
      bore: [78.5, [Validators.required, Validators.min(1), Validators.max(100000)]],
      strok: [82, [Validators.required, Validators.min(1), Validators.max(100000)]],
      n: [4, [Validators.required, Validators.min(1), Validators.max(1000)]]
    });

    this.form2 = this.fb.group({
      cubic: [1587.46, [Validators.required, Validators.min(1), Validators.max(10000000)]],
      rpm: [5000, [Validators.required, Validators.min(1), Validators.max(1000000)]],
      n: [4, [Validators.required, Validators.min(1), Validators.max(1000)]],
      psi: [0, [Validators.required, Validators.min(0), Validators.max(500)]]
    });

    this.form3 = this.fb.group({
      d: [243, [Validators.required, Validators.min(0), Validators.max(1000)]],
      rpm: [5000, [Validators.required, Validators.min(1), Validators.max(1000000)]],
      r: [3.36, [Validators.required, Validators.min(0), Validators.max(10000000)]]
    });

    this.form4 = this.fb.group({
      bore: [78.5, [Validators.required, Validators.min(0), Validators.max(1000)]],
      strok: [82, [Validators.required, Validators.min(0), Validators.max(1000000)]],
      bore_gasket: [80, [Validators.required, Validators.min(0), Validators.max(1000)]],
      strok_gasket: [0.65, [Validators.required, Validators.min(0), Validators.max(1000000)]],
      h_v: [37, [Validators.required, Validators.min(-1000000), Validators.max(10000000)]],
      p_v: [0, [Validators.required, Validators.min(-1000000), Validators.max(1000000)]]
    });

    this.form5 = this.fb.group({
      r: [3.36, [Validators.required, Validators.min(0), Validators.max(1000)]],
      r2: [2, [Validators.required, Validators.min(0), Validators.max(1000)]]
    });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.cubic_capacity = +(this.pi * this.form.value.bore *
            this.form.value.bore / 4 *
            this.form.value.strok / 1000 *
            this.form.value.n).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset() {

    this.cubic_capacity = 1587.46;

    this.form.setValue({
      bore: 78.5,
      strok: 82,
      n: 4
    });
  }

  onCalc4() {

    if (!this.form4.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          const gasket = +(this.pi * this.form4.value.bore_gasket *
            this.form4.value.bore_gasket / 4 *
            this.form4.value.strok_gasket / 1000);

          const motor = +(this.pi * this.form4.value.bore *
            this.form4.value.bore / 4 *
            this.form4.value.strok / 1000);

          const total_v = motor + gasket + (+this.form4.value.h_v) + (+this.form4.value.p_v);
          const left_v = gasket + (+this.form4.value.h_v) + (+this.form4.value.p_v);

          this.cr = +(total_v / left_v).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onCalc5() {

    if (!this.form5.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          let radius = (this.pi * (this.form5.value.r / 2) * (this.form5.value.r / 2));
          let newR = radius / ((this.form5.value.r2 / 2) * this.pi);

          this.runner_diameter2 = +(newR * 2).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset4() {

    this.cr = 10.86;

    this.form4.setValue({
      bore: 78.5,
      strok: 82,
      bore_gasket: 80,
      strok_gasket: 0.65,
      h_v: 37,
      p_v: 0
    });
  }

  onReset5() {

    this.runner_diameter2 = 5.64;
    // this.rType = '1';

    this.form5.setValue({
      r: 3.36,
      r2: 2
    });
  }

  onCalc2() {

    if (!this.form2.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          let r2 = 0;
          let r3 = 0;
          let bar = 1;
          // let p = 1.093;

          if (this.form2.value.psi > 0) {

            bar = (this.form2.value.psi / 14.5038) + 1;
            // p = p * bar;

            r2 = this.form2.value.cubic *
              this.form2.value.rpm / this.pi / 2.54 /
              this.form2.value.n / (this.m / 1.093 * bar * 1.1);

            r3 = this.form2.value.cubic *
              this.form2.value.rpm / this.pi / 2.54 /
              this.form2.value.n / (this.m2 / 1.292 * bar * 1.1);
          } else {

            r2 = this.form2.value.cubic *
              this.form2.value.rpm / this.pi / 2.54 /
              this.form2.value.n / this.m;

            r3 = this.form2.value.cubic *
              this.form2.value.rpm / this.pi / 2.54 /
              this.form2.value.n / this.m2;
          }

          this.runner_diameter = +(Math.sqrt(r2) * 2).toFixed(2);
          this.runner_diameter_max = +(Math.sqrt(r3) * 2).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset2() {

    this.runner_diameter = 3.36;
    this.runner_diameter_max = 3.51;

    this.m = 88200.0;
    this.m2 = 80850.0;

    this.form2.setValue({
      cubic: 1587.46,
      rpm: 5000,
      n: 4,
      psi: 0
    });
  }

  onCalc3() {

    if (!this.form3.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.runner_length1 = +(this.runnerlength(4)).toFixed(2);
          this.runner_length2 = +(this.runnerlength(8)).toFixed(2);
          this.runner_length3 = +(this.runnerlength(12)).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset3() {

    this.runner_length1 = 71.80;
    this.runner_length2 = 35.90;
    this.runner_length3 = 23.93;

    this.form3.setValue({
      d: 243,
      rpm: 5000,
      r: 3.36
    });
  }

  runnerlength(harmony) {
    return ((720 - this.form3.value.d) *
      this.v_sound / (12 * this.form3.value.rpm) +
      0.003 * this.form3.value.r) / harmony * 100;
  }

  onInfo(type: string) {

    switch (type) {
      case 'bore':
        this.presentActiveAlertConfirm('قطر سیلندر یا پیستون بر حسب میلیمتر');
        break;
      case 'strok':
        this.presentActiveAlertConfirm('کورس پیستون برحسب میلیمتر');
        break;
      case 'bore_gasket':
        this.presentActiveAlertConfirm('قطر واشر سرسیلندر (قطر حفره ی سیلندر و پیستون) بر حسب میلیمتر');
        break;
      case 'strok_gasket':
        this.presentActiveAlertConfirm('ضخامت واشر سرسیلندر برحسب میلیمتر');
        break;
      case 'h_v':
        this.presentActiveAlertConfirm('حجم فرو رفتگی یا همان گودی محفظه ی احتراق سرسیلندر برحسب سانتیمتر مکعب (cc)');
        break;
      case 'p_v':
        this.presentActiveAlertConfirm('حجم فرو رفتگی یا برآمدگی سر پیستون برحسب سانتیمتر مکعب (cc). دقت شود که پیستون برآمده باشد باید عدد منفی وارد شود');
        break;
      case 'n':
        this.presentActiveAlertConfirm('تعداد سیلندر');
        break;
      case 'cubic':
        this.presentActiveAlertConfirm('حجم موتوری که محاسبه کرده اید بر حسب سانتیمتر مکعب');
        break;
      case 'rpm':
        this.presentActiveAlertConfirm('دور موتور مد نظر شما');
        break;
      case 'd':
        this.presentActiveAlertConfirm('دوریشن میل سوپاپ برحسب درجه');
        break;
      case 'r':
        this.presentActiveAlertConfirm('قطر رانر محاسبه شده برحسب سانتیمتر');
        break;
      case 'r2':
        this.presentActiveAlertConfirm('قطر رانر محاسبه شده برحسب سانتیمتر');
        break;
      case 'r3':
        this.presentActiveAlertConfirm('قطر رانر مد نظر برحسب سانتیمتر');
        break;
      case 'psi':
        this.presentActiveAlertConfirm('اگر موتور اتمسفر است عدد 0، در غیر این صورت میزان بوست برحسب PSI');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
